values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'hearth' and v.version = '1.0.0'), 'contact', 'Contact details', '{"heading":"Come and see us","body":"Walk-ins are welcome. Call ahead for groups of six or more.","email":"hello@example.com","phone":"+91 00000 00000","address":"Your street address, City","hours":"Every day, 11am to 11pm"}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"heading":{"type":"string","minLength":1,"maxLength":200},"body":{"type":"string","minLength":1,"maxLength":2000},"email":{"type":"string","format":"email","pattern":"^(?:[A-Za-z0-9_''+\\-]+\\.)*[A-Za-z0-9_''+\\-]*[A-Za-z0-9_+-]@(?:[A-Za-z0-9][A-Za-z0-9\\-]*\\.)+[A-Za-z]{2,}$"},"phone":{"type":"string","minLength":3,"maxLength":30,"pattern":"^[+\\d][\\d\\s()-]*$"},"address":{"type":"string","minLength":1,"maxLength":200},"hours":{"type":"string","minLength":1,"maxLength":200}},"required":["heading"],"additionalProperties":false}'::jsonb, 80);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'hearth';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'hearth' and c.slug in ('restaurant', 'cafe', 'bakery', 'hotel');
